#ifndef XOMBE_CQ_Q15_TABLES_H
#define XOMBE_CQ_Q15_TABLES_H

/* int16 images of one set's PRBA codebooks for the q15 closed-loop quantizer's bounds (cquant.c), generated by
   scripts/gen_cq_tables.py. entries are rounded to nearest, so each is within 1/2 unit of its exact value
   r24 row i, pairs: (x0^2, x1^2), (x2^2, 2 x0 x1), (2 x0 x2, 2 x1 x2) at 2^-tm24, then (x0, x1), (x2, 0) at 2^-tx24
   r58 row j, pairs: (x0^2, x1^2), (x2^2, x3^2), (2 x0 x1, 2 x0 x2), (2 x0 x3, 2 x1 x2), (2 x1 x3, 2 x2 x3) at 2^-tm58,
   then (x0, x1), (x2, x3) at 2^-tx58, and a zero pair */

#include <stdint.h>
#include "../internal.h"

typedef struct {
    const uint32_t (*r24)[5];
    const uint32_t (*r58)[8];
    int tm24, tx24, tm58, tx58;
    float m24[6], x24[3]; /* max |entry| of each column over all rows, real units */
    float m58[10], x58[4];
    float n3, n4;         /* max |x|^2 over the usable rows, rounded up */
    int cnt;              /* usable prba58 rows: count, sums, and sums of products */
    float sx[4], sxx[4][4];
} xombe_cq_q15_tab;

extern const xombe_cq_q15_tab xombe__cq_q15_ambe2;
extern const xombe_cq_q15_tab xombe__cq_q15_dstar;

#endif
